import test from 'node:test';
import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
import {deflateSync} from 'node:zlib';
import {requireCandidate,validateReflection,normalizedDraw,expectedBinaryBytes,finalVerdict,requireFullFrame,decodePng,pixelDiff,sha256} from './validation.mjs';
import {compareCandidateTrees} from './driver.mjs';

const clone=x=>structuredClone(x),word=x=>Array.from(new Uint32Array(new Float64Array([x]).buffer));
const program={id:1,linked:true,street:true,vertex:'#undef USE_BATCHING\nvoid main(){}',fragment:'void main(){}',attributes:[{index:0,name:'position',size:1,type:35665,location:0},{index:1,name:'normal',size:1,type:35665,location:1},{index:2,name:'gl_VertexID',size:1,type:5124,location:-1}]};program.vertexSha256=sha256(program.vertex);program.fragmentSha256=sha256(program.fragment);
function fixture(){
 const sources=[{id:100,name:'source-0',corners:3},{id:101,name:'source-1',corners:3}],ranges=[{start:0,count:3,geometryId:0},{start:3,count:3,geometryId:1}];
 const catalog={groups:[{ordinal:0,material:7,sources,original:{ranges, indexType:null,buffers:{position:{nativeBuffer:11},normal:{nativeBuffer:12}}},indexed:{ranges:clone(ranges),indexType:'Uint32Array',buffers:{position:{nativeBuffer:21},normal:{nativeBuffer:22},index:{nativeBuffer:23}}}}]};
 const make=lane=>({object:'street-group-0',actualObjectId:lane==='indexed'?21:11,group:0,material:7,program:1,phase:'color',target:null,uniforms:[],state:{depthTest:true},transformWords:[0,1072693248],geometry:lane==='indexed'?2:1,method:lane==='indexed'?'multiDrawElementsWEBGL':'multiDrawArraysWEBGL',mode:4,indexType:lane==='indexed'?5125:null,drawCount:2,starts:lane==='indexed'?[0,12]:[0,3],counts:[3,3],indirect:[0,1],sortRows:[{start:0,count:3,index:0,z:.1,zWords:word(.1)},{start:3,count:3,index:1,z:.2,zWords:word(.2)}],reflectionAttributes:program.attributes,attributes:['position','normal'].map((name,i)=>({name,location:i,enabled:true,size:3,type:5126,normalized:false,stride:0,offset:0,divisor:0,buffer:(lane==='indexed'?21:11)+i})),elementBuffer:lane==='indexed'?23:null});
 return{catalog,a:make('original'),b:make('indexed'),programs:new Map([[1,program]])};
}
test('An unbound candidate can never satisfy the executable contract',()=>assert.throws(()=>requireCandidate({candidate:null}),/UNBOUND/));
test('The frozen plan has twenty distinct cases, seven predeclared controls and 160 fixed queries',async()=>{
 const p=JSON.parse(await readFile(new URL('./plan.json',import.meta.url))),pins=JSON.parse(await readFile(new URL('./pins.json',import.meta.url)));assert.equal(p.candidate,null);assert.equal(p.cases.length,20);assert.equal(new Set(p.cases.map(c=>c.name)).size,20);assert.equal(p.poses.length,5);assert.deepEqual(p.groupVisibilityControls.map(c=>c.group),[0,1,2,3,4,5,6]);assert(p.groupVisibilityControls.every(c=>p.cases.some(v=>v.name===c.case)&&c.witness.closestSource));assert.deepEqual(p.timing.blocks,[['original','indexed','indexed','original'],['indexed','original','original','indexed']]);assert.equal(p.timing.blocks.flat().length*p.cases.length,160);assert.equal(p.viewport.width,960);assert.equal(p.viewport.height,600);assert.equal(p.groups[1].indexType,'Uint32Array');assert.equal(p.groups[1].uniqueVertices,1052074);assert.equal(sha256(await readFile(new URL('./plan.json',import.meta.url))),pins.unboundPlanSha256);requireCandidate({candidate:pins.candidate});
});
test('Known built-in gl_VertexID reflection is accepted without an invented VBO',()=>{validateReflection(program);const p=clone(program);p.attributes=p.attributes.filter(a=>a.name!=='gl_VertexID');validateReflection(p);});
test('Malformed or unknown built-ins and negative user attribute locations are rejected',()=>{for(const change of [p=>p.attributes[2].type=5126,p=>p.attributes[2].name='gl_Unknown',p=>p.attributes[0].location=-1]){const p=clone(program);change(p);assert.throws(()=>validateReflection(p));}});
test('Street shaders may not enable vertex-ID-dependent morph geometry',()=>{const p=clone(program);p.vertex+='\n#define USE_MORPHTARGETS\n';p.vertexSha256=sha256(p.vertex);assert.throws(()=>validateReflection(p));});
test('Native arrays/elements offsets normalize to the same source/instance/triangle order',()=>{const{catalog,a,b,programs}=fixture();assert.deepEqual(normalizedDraw(a,catalog,'original',programs),normalizedDraw(b,catalog,'indexed',programs));});
test('Index byte width, native range offsets and count corruption fail independently',()=>{const{catalog,b,programs}=fixture();for(const mutate of [d=>d.starts[1]=3,d=>d.indexType=5123,d=>d.counts[1]=2,d=>d.indirect[1]=0,d=>d.attributes[0].buffer=11]){const d=clone(b);mutate(d);assert.throws(()=>normalizedDraw(d,catalog,'indexed',programs));}});
test('A reordered or fallback native street submission cannot normalize as equivalent',()=>{const{catalog,b,programs}=fixture();const d=clone(b);d.method='drawElements';assert.throws(()=>normalizedDraw(d,catalog,'indexed',programs));const e=clone(b);e.sortRows[0].z=.3;assert.throws(()=>normalizedDraw(e,catalog,'indexed',programs));});
test('Binary receipt formats have exact byte-count and endianness requirements',()=>{assert.equal(expectedBinaryBytes({kind:'binary',format:'Uint32',elements:1052074,endianness:'little'}),4208296);assert.equal(expectedBinaryBytes({kind:'pixels',format:'RGBA8-bottom-up',width:960,height:600}),2304000);assert.throws(()=>expectedBinaryBytes({kind:'binary',format:'Float64-matrix-bytes',elements:1,endianness:'little'}));assert.throws(()=>expectedBinaryBytes({kind:'binary',format:'Float32',elements:1,endianness:'big'}));});
test('Late page errors, failed requests and incomplete owned cleanup invalidate a prior audit',()=>{const r={validated:true,errors:[],requests:[],cleanup:{complete:true,errors:[]}};assert(finalVerdict(r));for(const change of [x=>x.errors.push('late page error'),x=>x.requests.push({failure:'late request'}),x=>x.cleanup.errors.push('close timeout'),x=>x.cleanup.complete=false]){const v=clone(r);change(v);assert.equal(finalVerdict(v),false);}});
test('Exactly the eight reviewed changes are allowed, including modes and unchanged leaves',()=>{const original=new Map([['untouched',{mode:'100644',type:'blob',blob:'a'.repeat(40)}]]),candidate=new Map(original),expected=Array.from({length:8},(_,i)=>({path:'changed-'+i,status:'added',mode:'100644',blob:String(i).repeat(40)}));for(const e of expected)candidate.set(e.path,{mode:e.mode,type:'blob',blob:e.blob});assert.equal(compareCandidateTrees(original,candidate,expected).length,8);const rogue=new Map(candidate);rogue.set('untouched',{mode:'100755',type:'blob',blob:'a'.repeat(40)});assert.throws(()=>compareCandidateTrees(original,rogue,expected));const missing=new Map(candidate);missing.delete('changed-2');assert.throws(()=>compareCandidateTrees(original,missing,expected));});
function crc(bytes){let c=0xffffffff;for(const b of bytes){c^=b;for(let k=0;k<8;k++)c=c&1?0xedb88320^(c>>>1):c>>>1;}return(c^0xffffffff)>>>0;}
function pngFixture(){const chunk=(type,data)=>{const b=Buffer.alloc(12+data.length);b.writeUInt32BE(data.length);b.write(type,4);data.copy(b,8);b.writeUInt32BE(crc(b.subarray(4,-4)),b.length-4);return b;};const header=Buffer.alloc(13);header.writeUInt32BE(1);header.writeUInt32BE(2,4);header[8]=8;header[9]=6;return Buffer.concat([Buffer.from('89504e470d0a1a0a','hex'),chunk('IHDR',header),chunk('IDAT',deflateSync(Buffer.from([0,1,2,3,255,0,9,8,7,255]))),chunk('IEND',Buffer.alloc(0))]);}
test('Independent PNG decoding verifies row orientation and rejects corrupt retained bytes',()=>{const png=pngFixture(),d=decodePng(png,1,2);assert.equal(d.readPixelsSha256,sha256(Buffer.from([9,8,7,255,1,2,3,255])));const bad=Buffer.from(png);bad[bad.length-1]^=1;assert.throws(()=>decodePng(bad,1,2));assert.throws(()=>decodePng(png.subarray(0,-1),1,2));assert.throws(()=>decodePng(png,2,1));});
test('One differing channel in one pixel never passes the zero-tolerance comparison',()=>assert.deepEqual(pixelDiff(Buffer.from([0,0,0,255,0,0,0,255]),Buffer.from([0,0,0,255,0,0,1,255])),{changedPixels:1,maxChannelDelta:1}));
test('A self-consistent crop cannot replace a complete frozen-viewport frame',()=>{const r={kind:'pixels',format:'RGBA8-bottom-up',width:960,height:600,bytes:2304000,png:true};requireFullFrame(r,960,600);assert.throws(()=>requireFullFrame({...r,width:1,height:1,bytes:4},960,600));assert.throws(()=>requireFullFrame({...r,png:false},960,600));});
